    public let controlOn, controlGlyph, controlFill, controlTrack, controlThumb, controlThumbOn: Color
    /// Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4.
    public let series: [Color]

    public static let light = ManicatTokens(
        background: Color(hex: "#ffffff"), surface: Color(hex: "#ffffff"), surfaceRaised: Color(hex: "#ffffff"), surfaceMuted: Color(hex: "#f8f8f8"),
